def hop_distances(edges: list[tuple[str, str]], src: str) -> dict[str, int]:
    """`edges` lists the edges of a graph whose nodes are strings. Each edge (a, b) is DIRECTED: it can only be travelled from a to b.
    Return a dict mapping every node reachable from `src` (including `src` itself, at
    distance 0, even if it appears in no edge) to its distance in edges.
    Duplicate edges and self-loops may occur.

    >>> hop_distances([('x', 'y'), ('y', 'z')], 'x')
    {'x': 0, 'y': 1, 'z': 2}
    """
    from collections import deque
    adj = {}
    for a, b in edges:
        adj.setdefault(a, []).append(b)
    dist = {src: 0}
    queue = deque([src])
    while queue:
        node = queue.popleft()
        for nxt in adj.get(node, []):
            if nxt not in dist:
                dist[nxt] = dist[node] + 1
                queue.append(nxt)
    return dist

