def min_hops(edges: list[tuple[str, str]], src: str, dst: str) -> int:
    """`edges` lists the edges of a graph whose nodes are strings. Each edge (a, b) is DIRECTED: it can only be travelled from a to b.
    Return the minimum number of edges on a path from `src` to `dst`: 0 when they
    are the same node (even if it appears in no edge), -1 if `dst` is unreachable.
    Duplicate edges and self-loops may occur.

    >>> min_hops([('x', 'y'), ('y', 'z')], 'x', 'z')
    2
    """
    from collections import deque
    adj = {}
    for a, b in edges:
        adj.setdefault(a, []).append(b)
    dist = {src: 0}
    queue = deque([src])
    while queue:
        node = queue.popleft()
        for nxt in adj.get(node, []):
            if nxt not in dist:
                dist[nxt] = dist[node] + 1
                queue.append(nxt)
    return dist.get(dst, -1)

