canonical_solution:
def bracket_depth(text: str) -> int:
    """Check the brackets in `text`. The bracket pairs are '[]', '{}', '()'; every other
    character (including any other bracket-like character) is ignored.

    If the brackets are balanced and properly nested, return the maximum nesting
    depth (0 when there are no brackets); otherwise return -1.

    >>> bracket_depth('[{}]')
    2
    """
    pairs = {']': '[', '}': '{', ')': '('}
    stack = []
    depth = 0
    for i, ch in enumerate(text):
        if ch in '[{(':
            stack.append(ch)
            depth = max(depth, len(stack))
        elif ch in pairs:
            if not stack or stack[-1] != pairs[ch]:
                return -1
            stack.pop()
    return -1 if stack else depth

