canonical_solution:
def step_combinations(coins: list[int], amount: int) -> int:
    """Return the number of ways to make exactly `amount` from `coins`.

    `coins` holds DISTINCT positive values, each usable any number of times, and
    ORDER MATTERS: 1+2 and 2+1 are different ways.
    The amount 0 can be made in exactly 1 way (use nothing); a negative amount in 0 ways.

    >>> step_combinations([1, 2, 3], 4)
    7
    """
    if amount < 0:
        return 0
    ways = [1] + [0] * amount
    for a in range(1, amount + 1):
        for c in coins:
            if c <= a:
                ways[a] += ways[a - c]
    return ways[amount]

