canonical_solution:
def flatten_keys(data: dict) -> dict:
    """Flatten the nested dict `data` into a single-level dict.

    Every value that is not a dict is stored under the path of keys leading to
    it, joined with '/'. Keys are converted with str(), so the int key 3
    contributes '3'. Lists and other non-dict values are kept as they are (not
    descended into). An empty nested dict is kept as a value: its path maps to {}.
    An empty `data` gives {}. Keys are never empty and never contain '/'.

    >>> flatten_keys({'a': {'b': 1, 'c': {'d': 2}}, 'e': 3})
    {'a/b': 1, 'a/c/d': 2, 'e': 3}
    """
    out = {}

    def walk(prefix, node):
        for key, value in node.items():
            path = prefix + '/' + str(key) if prefix else str(key)
            if isinstance(value, dict) and value:
                walk(path, value)
            elif isinstance(value, dict):
                out[path] = {}
            else:
                out[path] = value

    walk("", data)
    return out

