canonical_solution:
def path_count(grid: list[str]) -> int:
    """`grid` is a list of equal-length strings; '*' cells are blocked and every
    other character is open. Count the paths from the top-left cell to the
    bottom-right cell that only visit open cells, where each move is one step right, one step down, or one step diagonally down-right.

    If the start or end cell is blocked the answer is 0; a 1x1 open grid has
    exactly 1 path. An empty grid (or empty rows) gives 0.

    >>> path_count(['..', '..'])
    3
    """
    if not grid or not grid[0]:
        return 0
    rows, cols = len(grid), len(grid[0])
    ways = [[0] * cols for _ in range(rows)]
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == '*':
                continue
            if r == 0 and c == 0:
                ways[r][c] = 1
                continue
            total = 0
            if r > 0:
                total += ways[r - 1][c]
            if c > 0:
                total += ways[r][c - 1]
            if r > 0 and c > 0:
                total += ways[r - 1][c - 1]
            ways[r][c] = total
    return ways[rows - 1][cols - 1]

