def bucket_words(words: list[str]) -> dict:
    """Group the non-empty strings in `words` by their first character, lowercased.

    Return a dict mapping each key to the list of words having that key,
    sorted in ascending string order with exact duplicates removed. Words keep their original spelling. Empty strings are ignored;
    an empty input gives {}.

    >>> bucket_words(['ant', 'Bee', 'art', 'bat'])
    {'a': ['ant', 'art'], 'b': ['Bee', 'bat']}
    """
    groups = {}
    for w in words:
        if not w:
            continue
        key = w[0].lower()
        groups.setdefault(key, []).append(w)
    for k in groups:
        groups[k] = sorted(set(groups[k]))
    return groups

