    Return a dict mapping each key to the list of words having that key,
    in the order they appear in `words` (duplicates kept). Words keep their original spelling. Empty strings are ignored;
    an empty input gives {}.

    >>> bucket_words(['ant', 'Bee', 'art', 'bat'])
    {'a': ['ant', 'art'], 'b': ['Bee', 'bat']}
    """
    groups = {}
    for w in words:
        if not w:
            continue
        key = w[0].lower()
        groups.setdefault(key, []).append(w)
    return groups

