def invert_dict(mapping: dict[str, int]) -> dict:
    """Invert `mapping` (str keys, int values): each distinct value becomes a key that
    maps to the FIRST key (in insertion order) that had it.

    Every distinct value appears exactly once in the result.
    An empty mapping gives {}.

    >>> invert_dict({'a': 1, 'b': 2, 'c': 1})
    {1: 'a', 2: 'b'}
    """
    out = {}
    for k, v in mapping.items():
        if v not in out:
            out[v] = k
    return out

