canonical_solution:
def count_primes(lo: int, hi: int) -> int:
    """Consider the integers m with lo <= m < hi (hi excluded).
    Return how many of them are prime.

    A prime is an integer greater than 1 whose only positive divisors are 1 and
    itself, so 0, 1 and negative numbers are never prime. If the range is empty
    (for example lo > hi) the result is 0.

    >>> count_primes(10, 20)
    4
    """
    def is_prime(m):
        if m < 2:
            return False
        i = 2
        while i * i <= m:
            if m % i == 0:
                return False
            i += 1
        return True
    primes = [m for m in range(lo, hi) if is_prime(m)]
    return len(primes)

