canonical_solution:
def spiral_order(grid: list[list[int]]) -> list[int]:
    """Return every element of the rectangular matrix `grid` exactly once, in spiral order.

    Start at the top-left corner and walk CLOCKWISE: right along the top row,
    down the right column, left along the bottom row, up the left column, then
    continue with the next inner ring.
    An empty matrix ([] or rows with no entries) gives [].

    >>> spiral_order([[1, 2], [3, 4]])
    [1, 2, 4, 3]
    """
    result = []
    if not grid or not grid[0]:
        return result
    top, bottom, left, right = 0, len(grid) - 1, 0, len(grid[0]) - 1
    while top <= bottom and left <= right:
        for c in range(left, right + 1):
            result.append(grid[top][c])
        for r in range(top + 1, bottom + 1):
            result.append(grid[r][right])
        if top < bottom:
            for c in range(right - 1, left - 1, -1):
                result.append(grid[bottom][c])
        if left < right:
            for r in range(bottom - 1, top, -1):
                result.append(grid[r][left])
        top += 1
        bottom -= 1
        left += 1
        right -= 1
    return result

