def stack_machine(program: list[str]) -> int | None:
    """Run `program`, a list of instruction strings, on an initially empty stack and
    return the value on top of the final stack, or None if the final stack is empty.

    Instructions:
    - 'push N' pushes the integer N (N may be negative).
    - 'pop' removes the top value; 'dup' pushes a copy of the top value.
    - 'swap' exchanges the top two values.
    - 'add', 'sub' and 'mul' pop the top value b, then the next value a, and push
      a + b, b - a, and a * b respectively.

    If an instruction needs more values than the stack holds (one for pop/dup,
    two for swap/add/sub/mul), execution stops immediately and the function returns None.

    >>> stack_machine(['push 2', 'push 5', 'sub'])
    3
    """
    stack = []
    need = {"pop": 1, "dup": 1, "swap": 2, "add": 2, "sub": 2, "mul": 2}
    for ins in program:
        parts = ins.split()
        op = parts[0]
        if op == "push":
            stack.append(int(parts[1]))
            continue
        if len(stack) < need[op]:
            return None
        if op == "pop":
            stack.pop()
        elif op == "dup":
            stack.append(stack[-1])
        elif op == "swap":
            stack[-1], stack[-2] = stack[-2], stack[-1]
        else:
            b = stack.pop()
            a = stack.pop()
            if op == "add":
                stack.append(a + b)
            elif op == "sub":
                stack.append(b - a)
            else:
                stack.append(a * b)
    return stack[-1] if stack else None

